#include <cstddef>
#include <span>
#include <vector>

class Particles
{
public:
    std::size_t add(float x, float y, float vx, float vy)
    {
        m_x.push_back(x);
        m_y.push_back(y);
        m_vx.push_back(vx);
        m_vy.push_back(vy);
        return m_x.size() - 1;
    }

    std::size_t size() const { return m_x.size(); }

    void step(float dt)
    {
        for (std::size_t i{ 0 }; i < m_x.size(); ++i) m_x[i] += m_vx[i] * dt;
        for (std::size_t i{ 0 }; i < m_y.size(); ++i) m_y[i] += m_vy[i] * dt;
    }

    std::span<const float> xs() const { return m_x; }
    std::span<const float> ys() const { return m_y; }

    float kineticEnergy() const
    {
        float total{ 0.0f };
        for (std::size_t i{ 0 }; i < m_vx.size(); ++i)
        {
            total += 0.5f * (m_vx[i] * m_vx[i] + m_vy[i] * m_vy[i]);
        }
        return total;
    }

    void remove(std::size_t index)
    {
        for (std::vector<float>* field : { &m_x, &m_y, &m_vx, &m_vy })
        {
            (*field)[index] = field->back();
            field->pop_back();
        }
    }

private:
    std::vector<float> m_x{};
    std::vector<float> m_y{};
    std::vector<float> m_vx{};
    std::vector<float> m_vy{};
};

unitTests:
TEST("add and size") { Particles p{}; CHECK_EQ(p.size(), 0u); CHECK_EQ(p.add(1.f, 2.f, 0.f, 0.f), 0u); CHECK_EQ(p.add(3.f, 4.f, 0.f, 0.f), 1u); CHECK_EQ(p.size(), 2u); CHECK_EQ(p.xs().size(), 2u); CHECK_NEAR(p.xs()[1], 3.0, 1e-6); CHECK_NEAR(p.ys()[0], 2.0, 1e-6); }
TEST("step moves everything") { Particles p{}; p.add(0.f, 0.f, 2.f, -1.f); p.add(10.f, 10.f, 0.f, 4.f); p.step(0.5f); CHECK_NEAR(p.xs()[0], 1.0, 1e-6); CHECK_NEAR(p.ys()[0], -0.5, 1e-6); CHECK_NEAR(p.xs()[1], 10.0, 1e-6); CHECK_NEAR(p.ys()[1], 12.0, 1e-6); }
TEST("kineticEnergy") { Particles p{}; CHECK_NEAR(p.kineticEnergy(), 0.0, 1e-6); p.add(0.f, 0.f, 3.f, 4.f); p.add(0.f, 0.f, 1.f, 0.f); CHECK_NEAR(p.kineticEnergy(), 13.0, 1e-5); }
TEST("remove keeps the four arrays in step") { Particles p{}; p.add(1.f, 10.f, 1.f, 0.f); p.add(2.f, 20.f, 2.f, 0.f); p.add(3.f, 30.f, 3.f, 0.f); p.remove(0); CHECK_EQ(p.size(), 2u); CHECK_NEAR(p.xs()[0], 3.0, 1e-6); CHECK_NEAR(p.ys()[0], 30.0, 1e-6); p.step(1.0f); CHECK_NEAR(p.xs()[0], 6.0, 1e-6); CHECK_NEAR(p.xs()[1], 4.0, 1e-6); p.remove(1); p.remove(0); CHECK_EQ(p.size(), 0u); CHECK_EQ(p.ys().size(), 0u); }
TEST("each field is one contiguous block") { Particles p{}; for (int i{ 0 }; i < 100; ++i) p.add(static_cast<float>(i), 0.f, 0.f, 0.f); const auto xs{ p.xs() }; CHECK(&xs[99] - &xs[0] == 99); CHECK_NEAR(xs[57], 57.0, 1e-6); }

